CHAPTERS=[('II/01', 'The Real Number System and Completeness', 'ch01_the_real_number_system_and_completeness'), ('II/02', 'Euclidean and Normed Spaces', 'ch02_euclidean_and_normed_spaces'), ('II/03', 'Sequences and Cauchy Sequences', 'ch03_sequences_and_cauchy_sequences'), ('II/04', 'Open and Closed Sets', 'ch04_open_and_closed_sets'), ('II/05', 'Metric Spaces and Continuity', 'ch05_metric_spaces_and_continuity'), ('II/06', 'Compactness', 'ch06_compactness'), ('II/07', 'Connectedness and Path Connectedness', 'ch07_connectedness_and_path_connectedness'), ('II/08', 'Differentiability in Several Variables', 'ch08_differentiability_in_several_variables'), ('II/09', 'Inverse and Implicit Function Principles', 'ch09_inverse_and_implicit_function_principles'), ('II/10', 'Riemann Integration', 'ch10_riemann_integration'), ('II/11', 'Pointwise and Uniform Convergence', 'ch11_pointwise_and_uniform_convergence'), ('II/12', 'Interchanging Limits, Derivatives and Integrals', 'ch12_interchanging_limits_derivatives_and_integrals'), ('II/13', 'Infinite Series of Functions', 'ch13_infinite_series_of_functions'), ('II/14', 'Trigonometric Series', 'ch14_trigonometric_series'), ('II/15', 'Pathological and Nowhere-Differentiable Functions', 'ch15_pathological_and_nowhere_differentiable_functions'), ('II/16', 'Contraction Mappings', 'ch16_contraction_mappings'), ('II/17', 'Brouwer-Type Fixed-Point Ideas', 'ch17_brouwer_type_fixed_point_ideas'), ('II/18', 'Integral Equations', 'ch18_integral_equations'), ('II/19', 'Elementary Existence Theory for ODEs', 'ch19_elementary_existence_theory_for_odes'), ('II/20', 'Polynomial Interpolation', 'ch20_polynomial_interpolation'), ('II/21', 'Polynomial Approximation', 'ch21_polynomial_approximation'), ('II/22', 'Chebyshev and Minimax Approximation', 'ch22_chebyshev_and_minimax_approximation'), ('II/23', 'The Alternation Principle', 'ch23_the_alternation_principle'), ('II/24', 'Numerical Quadrature', 'ch24_numerical_quadrature'), ('II/25', 'Continued Fractions and Approximation Topics', 'ch25_continued_fractions_and_approximation_topics')]
DATA={'II/01': {'intro': 'The real numbers are an ordered field completed by a least-upper-bound principle. Completeness converts approximation into existence and drives the convergence arguments used throughout analysis.', 'sections': [('Ordered fields', 'Order is compatible with addition and multiplication. Positivity, trichotomy, and cancellation permit algebraic manipulation of inequalities.'), ('Bounds and extrema', 'Upper and lower bounds describe sets globally; maxima and minima are bounds attained by elements of the set.'), ('Suprema and infima', 'The supremum is the least upper bound and the infimum the greatest lower bound. Neither need belong to the set.'), ('Completeness', 'Every nonempty real set bounded above has a supremum. This property fails in the rational numbers.'), ('Archimedean property', 'No real number dominates all positive integers; equivalently, reciprocals of positive integers can be made arbitrarily small.'), ('Density', 'Between distinct real numbers lie both rational and irrational numbers.'), ('Absolute value and inequalities', 'Absolute value is the one-dimensional norm and satisfies triangle and reverse-triangle inequalities.'), ('Nested intervals and roots', 'Completeness yields nested-interval principles and existence of positive square roots.')], 'theorems': [('Archimedean property', 'For every real $x$ there is $n\\in\\mathbb N$ with $n>x$.', 'Otherwise $\\mathbb N$ would have a supremum $s$; then $s-1$ would fail to be an upper bound, producing $n>s-1$ and hence $n+1>s$, contradiction.'), ('Supremum approximation', 'If $s=\\sup A$ and $\\varepsilon>0$, some $a\\in A$ satisfies $s-\\varepsilon<a\\le s$.', 'If not, $s-\\varepsilon$ would itself be an upper bound, contradicting the leastness of $s$.'), ('Square-root existence', 'For every $a>0$ there is a unique $r>0$ with $r^2=a$.', 'Take $r=\\sup\\{x\\ge0:x^2\\le a\\}$. If $r^2<a$, a small increase remains admissible; if $r^2>a$, a small decrease remains an upper bound. Both contradict the definition of $r$.')], 'dossiers': [('Supremum of a quadratic set', 'Let $A=\\{x\\ge0:x^2<5\\}$. Identify $\\sup A$.', 'The set is nonempty and bounded. Its supremum $s$ must satisfy $s^2=5$ by the square-root supremum argument, so $s=\\sqrt5$.'), ('Infimum by reflection', 'Prove $\\inf A=-\\sup(-A)$ for nonempty $A$ bounded below.', 'Lower bounds of $A$ correspond under sign change to upper bounds of $-A$; reversing the order turns the least upper bound into the greatest lower bound.'), ('No largest rational below an irrational', 'If $\\alpha$ is irrational, show $\\{q\\in\\mathbb Q:q<\\alpha\\}$ has no maximum.', 'Given $q<\\alpha$, density of $\\mathbb Q$ gives a rational $r$ with $q<r<\\alpha$.'), ('Reciprocals become small', 'Given $\\varepsilon>0$, prove some $n$ satisfies $1/n<\\varepsilon$.', 'Choose $n>1/\\varepsilon$ by the Archimedean property and take reciprocals.'), ('Integer bracketing', 'Show every $x\\in\\mathbb R$ satisfies $m\\le x<m+1$ for some $m\\in\\mathbb Z$.', 'Use the Archimedean property to restrict to finitely many candidate integers and choose the largest integer not exceeding $x$.'), ('Rational density', 'Prove that $x<y$ implies there is rational $q$ with $x<q<y$.', 'Choose $n$ with $1/n<y-x$ and then an integer $m$ with $nx<m\\le nx+1$; $m/n$ lies between $x$ and $y$.'), ('Irrational density', 'Prove there is an irrational number between any two reals.', 'Choose rational $r$ in $(x-\\sqrt2,y-\\sqrt2)$ and use $r+\\sqrt2$.'), ('Reverse triangle inequality', 'Prove $||x|-|y||\\le|x-y|$.', 'Apply the triangle inequality to $x=(x-y)+y$ and then interchange $x,y$.'), ('Nested intervals are unique when lengths vanish', 'If nested closed intervals have lengths tending to zero, show their intersection has at most one point.', 'Two common points would have distance bounded by every interval length, hence by arbitrarily small positive numbers, so they coincide.'), ('Why $\\mathbb Q$ is incomplete', 'Explain why $\\{q\\in\\mathbb Q:q^2<2,q\\ge0\\}$ has no rational supremum.', 'Its real supremum is $\\sqrt2$, and any rational candidate below or above can be improved using the order argument; $\\sqrt2\\notin\\mathbb Q$.'), ('Geometric partial sums', 'Find the supremum of $1+1/2+\\cdots+1/2^n$.', 'The sum equals $2-2^{-n}$, so $2$ is an upper bound approached arbitrarily closely and hence is the supremum.'), ('Completeness synthesis', 'Explain how a supremum packages arbitrarily accurate lower approximations into one number.', 'Completeness supplies $s=\\sup A$, and supremum approximation places elements of $A$ within every positive distance below $s$.')], 'exercises': [('Find $\\sup\\{n/(n+1):n\\ge1\\}$.', 'Compare with $1$.', 'The supremum is $1$.'), ('Find $\\inf\\{1/n:n\\ge1\\}$.', 'Use Archimedean smallness.', 'The infimum is $0$.'), ('Solve $|2x-1|\\le3$.', 'Use a double inequality.', 'The solution is $[-1,2]$.'), ('Show $|x+y|\\ge||x|-|y||$.', 'Apply reverse triangle inequality.', 'It is the reverse triangle inequality with $x$ and $-y$.'), ('Give a bounded rational set with no rational supremum.', 'Use $q^2<3$.', '$\\{q\\in\\mathbb Q:q^2<3,q\\ge0\\}$ works.'), ('Show every finite nonempty real set has a maximum.', 'Induct on the cardinality.', 'Adjoin one element at a time and take the larger of it and the previous maximum.'), ('If $A\\subset B$, compare suprema.', 'Every upper bound of $B$ bounds $A$.', 'When both exist, $\\sup A\\le\\sup B$.'), ('If $|x-y|<\\varepsilon$ for every $\\varepsilon>0$, show $x=y$.', 'Assume positive distance.', 'Take $\\varepsilon=|x-y|/2$ to obtain a contradiction.')]}, 'II/02': {'intro': 'Normed spaces add quantitative geometry to vector spaces. The norm axioms isolate exactly the estimates needed to speak about distance, convergence, boundedness, and continuity.', 'sections': [('Euclidean norm', 'The Euclidean norm is induced by the standard inner product and measures ordinary length.'), ('Norm axioms', 'A norm is positive definite, absolutely homogeneous, and subadditive.'), ('Standard finite-dimensional norms', 'The $1$-, $2$-, and infinity norms emphasize total magnitude, Euclidean length, and largest coordinate.'), ('Balls and spheres', 'Norm balls define neighborhoods and therefore the topology of a normed space.'), ('Operator norms', 'The induced norm of a linear map measures its maximal stretching on the unit sphere.'), ('Equivalent norms', 'Comparable norms define the same convergence and open sets.'), ('Convexity', 'Every norm ball is convex by the triangle inequality.'), ('Finite versus infinite dimensions', 'All norms are equivalent in finite dimensions, but this can fail in infinite-dimensional spaces.')], 'theorems': [('Cauchy--Schwarz', 'For $x,y\\in\\mathbb R^n$, $|\\langle x,y\\rangle|\\le\\|x\\|_2\\|y\\|_2$.', 'Apply nonnegativity to $\\|x-ty\\|_2^2$ and require its quadratic discriminant to be nonpositive.'), ('Euclidean triangle inequality', '$\\|x+y\\|_2\\le\\|x\\|_2+\\|y\\|_2$.', 'Expand the square and use Cauchy--Schwarz on the cross term.'), ('Norm comparison', 'On $\\mathbb R^n$, $\\|x\\|_\\infty\\le\\|x\\|_2\\le\\sqrt n\\|x\\|_\\infty$.', 'The largest coordinate square is bounded by the sum of squares, and each coordinate square is bounded by the largest one.')], 'dossiers': [('Compare $1$- and $2$-norms', 'Prove $\\|x\\|_2\\le\\|x\\|_1\\le\\sqrt n\\|x\\|_2$.', 'The first follows by expanding $(\\sum|x_i|)^2$; the second is Cauchy--Schwarz against $(1,\\dots,1)$.'), ('A seminorm, not a norm', 'Is $p(x,y)=|x-y|$ a norm on $\\mathbb R^2$?', 'No: $p(1,1)=0$ although $(1,1)\\ne0$.'), ('Weighted Euclidean norm', 'Show $\\sqrt{4x^2+y^2}$ is a norm.', 'It is the Euclidean norm after the invertible linear change $(x,y)\\mapsto(2x,y)$.'), ('Distance to a coordinate axis', 'Find the Euclidean distance from $(1,2)$ to the $x$-axis.', 'Minimizing $(1-t)^2+4$ over $(t,0)$ gives $t=1$ and distance $2$.'), ('Projection operator norm', 'For $P(x,y)=(x,0)$, find $\\|P\\|_2$.', '$\\|P(x,y)\\|\\le\\|(x,y)\\|$ and equality holds at $(1,0)$, so $\\|P\\|=1$.'), ('Equivalent convergence', 'Show $\\|x_n-x\\|_2\\to0$ iff $\\|x_n-x\\|_\\infty\\to0$.', 'Use $\\|z\\|_\\infty\\le\\|z\\|_2\\le\\sqrt n\\|z\\|_\\infty$.'), ('Diameter of the unit sphere', 'If $\\|x\\|=\\|y\\|=1$, show $\\|x-y\\|\\le2$.', 'Use the triangle inequality on $x+(-y)$.'), ('Reverse triangle inequality', 'Prove $|\\|x\\|-\\|y\\||\\le\\|x-y\\|$.', 'Apply the triangle inequality to $x=(x-y)+y$ and then swap $x,y$.'), ('Norm of a Euclidean functional', 'For $f(x)=a\\cdot x$, compute $\\|f\\|$.', 'Cauchy--Schwarz gives $\\|f\\|\\le\\|a\\|_2$, with equality at $x=a/\\|a\\|_2$.'), ('Convexity of closed balls', 'Prove every closed norm ball is convex.', 'A convex combination of two radius-$r$ displacement vectors has norm at most the same convex combination of their norms, hence at most $r$.'), ('Infinite-dimensional warning', 'Why is there no $C$ with $\\|f\\|_\\infty\\le C\\|f\\|_1$ for every continuous $f$ on $[0,1]$?', 'Continuous spike functions can keep height $1$ while their support and integral shrink to zero.'), ('Equivalent-norm synthesis', 'Why do two-sided norm bounds imply identical topology?', 'Each ball for one norm contains a suitably scaled ball for the other, in both directions.')], 'exercises': [('Compute all three standard norms of $(1,-1,2)$.', 'Use definitions.', 'They are $4,\\sqrt6,2$.'), ('Show $2|x|+3|y|$ is a norm.', 'Check the axioms.', 'Positive weighted sums of absolute values satisfy the norm axioms.'), ('Is $\\max(|x|,2|y|)$ a norm?', 'View it as a weighted infinity norm.', 'Yes.'), ('Find the Euclidean distance from $(1,2)$ to $(-2,6)$.', 'Subtract first.', 'The difference has length $5$.'), ('Prove $\\|0\\|=0$.', 'Use homogeneity with scalar zero.', '$\\|0x\\|=0\\|x\\|=0$.'), ('If $x_n\\to x$, show $\\|x_n\\|\\to\\|x\\|$.', 'Use reverse triangle inequality.', 'The norm difference is bounded by $\\|x_n-x\\|$.'), ('Find the operator norm of $T(x,y)=(3x,0)$.', 'Bound and attain.', 'The norm is $3$.'), ('Show the open unit ball is convex.', 'Use strict norm bounds.', 'A convex combination has norm below the corresponding convex combination of two numbers below $1$.')]}, 'II/03': {'intro': 'Sequences encode limiting behavior through quantifiers. Cauchy sequences compare late terms only with each other, and completeness is exactly the principle that such internal coherence produces a limit.', 'sections': [('Convergence', 'A sequence converges when all sufficiently late terms lie in every prescribed neighborhood of a candidate limit.'), ('Uniqueness', 'Metric separation makes limits unique.'), ('Boundedness', 'Every convergent sequence is bounded, but boundedness alone does not force convergence.'), ('Subsequences', 'Subsequences preserve order and are the basic tool for detecting hidden limiting behavior.'), ('Cauchy sequences', 'A sequence is Cauchy when sufficiently late terms are mutually close.'), ('Completeness', 'A metric space is complete if every Cauchy sequence converges in the space.'), ('Monotone real sequences', 'Bounded monotone real sequences converge by the supremum property.'), ('Limsup and liminf', 'Tail suprema and infima capture asymptotic oscillation.')], 'theorems': [('Convergent implies Cauchy', 'Every convergent sequence in a metric space is Cauchy.', 'Choose a tail within $\\varepsilon/2$ of the limit and apply the triangle inequality.'), ('Monotone convergence', 'Every increasing real sequence bounded above converges to the supremum of its range.', 'Supremum approximation supplies one late term within $\\varepsilon$ below the supremum; monotonicity traps every later term.'), ('Cauchy boundedness', 'Every Cauchy sequence is bounded.', 'A tail lies in a unit ball about one tail term; combine this with the finite initial segment.')], 'dossiers': [('Direct proof for $1/n$', 'Prove $1/n\\to0$.', 'Given $\\varepsilon>0$, choose $N>1/\\varepsilon$.'), ('Uniqueness of limits', 'Prove a metric sequence cannot converge to two distinct points.', 'The triangle inequality would make the distance between the two proposed limits smaller than itself.'), ('Convergent implies bounded', 'Prove it without invoking a theorem name.', 'Take a tail in a unit ball around the limit and enlarge the ball to contain the finite initial segment.'), ('Subsequence inheritance', 'Show every subsequence of a convergent sequence has the same limit.', 'Subsequence indices eventually exceed any original convergence index.'), ('A Cauchy sequence in $\\mathbb Q$ without rational limit', 'Use rational truncations of $\\sqrt2$.', 'They converge in $\\mathbb R$ and are therefore Cauchy, but a rational limit would equal $\\sqrt2$ by uniqueness.'), ('Geometric-series Cauchy criterion', 'Show partial sums of $\\sum r^k$ are Cauchy for $|r|<1$.', 'Bound every tail by $|r|^{n+1}/(1-|r|)$.'), ('Recursive monotone convergence', 'For $x_{n+1}=\\sqrt{2+x_n}$, $x_1=1$, prove $x_n\\to2$.', 'Inductively the sequence is increasing and bounded by $2$; its limit satisfies $L^2=L+2$ and positivity forces $L=2$.'), ('Bounded but divergent', 'Analyze $(-1)^n$.', 'Even and odd subsequences converge to different values, so the full sequence diverges.'), ('Limsup and liminf', 'Find them for $(-1)^n+1/n$.', 'Even and odd subsequences approach $1$ and $-1$, giving limsup $1$ and liminf $-1$.'), ('Cauchy plus a convergent subsequence', 'Prove the whole sequence converges to the subsequential limit.', 'Use one late subsequence term as a bridge between the Cauchy tail and the limit.'), ('Completeness of reals via tail bounds', 'Explain how a Cauchy real sequence can be trapped by tail infima and suprema.', 'Tail infima increase, tail suprema decrease, and their gap tends to zero; completeness gives a common limiting value.'), ('Sequence synthesis', 'Distinguish convergence from the Cauchy property conceptually.', 'Convergence references an external limit; Cauchy behavior is internal. Completeness connects the two.')], 'exercises': [('Prove $3/n\\to0$.', 'Choose $N>3/\\varepsilon$.', 'Then $n\\ge N$ implies $3/n<\\varepsilon$.'), ('Does $(-1)^n/n$ converge?', 'Bound the absolute value.', 'Yes, to $0$.'), ('Show every constant sequence is Cauchy.', 'Distances vanish.', 'Every pairwise distance is zero.'), ('If $x_n\\to x$, prove $x_{n+1}\\to x$.', 'It is a tail subsequence.', 'The same epsilon estimate applies.'), ('Find $\\lim n/(n+1)$.', 'Rewrite the expression.', 'It is $1$.'), ('Give a bounded divergent sequence.', 'Use alternating signs.', '$(-1)^n$ works.'), ('What happens to an increasing bounded real sequence?', 'Use monotone convergence.', 'It converges to the supremum of its range.'), ('Show a Cauchy tail is bounded.', 'Use epsilon $1$.', 'Eventually all terms lie in a unit ball around one fixed tail term.')]}, 'II/04': {'intro': 'Open and closed sets encode local and limiting structure without coordinates. Interiors, closures, boundaries, and limit points become the language in which continuity and topology are most naturally expressed.', 'sections': [('Open sets', 'A set is open if every one of its points contains a ball lying entirely in the set.'), ('Closed sets', 'A set is closed if its complement is open; in metric spaces this is equivalent to containing limits of convergent sequences from the set.'), ('Interior', 'The interior is the largest open subset contained in a set.'), ('Closure', 'The closure is the smallest closed set containing the set.'), ('Limit points', 'A point is a limit point if every punctured neighborhood meets the set.'), ('Boundary', 'Boundary points have every neighborhood meeting both the set and its complement.'), ('Set operations', 'Arbitrary unions and finite intersections preserve openness; dual statements hold for closed sets.'), ('Relative topology and density', 'Relative openness is obtained by intersecting ambient open sets with a subspace, while density means the closure fills the ambient space.')], 'theorems': [('Open-set operations', 'Arbitrary unions and finite intersections of open sets are open.', 'For unions inherit a ball from one containing member; for finite intersections take the minimum of finitely many available radii.'), ('Sequential closedness', 'A metric subset is closed iff it contains every limit of every convergent sequence drawn from it.', 'Closedness prevents a convergent sequence from entering an open complement; conversely a point in the closure but outside the set yields points within $1/n$ converging to it.'), ('Closure by balls', '$x\\in\\overline A$ iff every ball centered at $x$ meets $A$.', 'A ball missing $A$ places $x$ in the open complement of the closure; the converse is immediate from the same characterization.')], 'dossiers': [('Interval anatomy', 'Find the interior, closure, and boundary of $(0,1]$.', 'They are $(0,1)$, $[0,1]$, and $\\{0,1\\}$.'), ('Open balls are open', 'Prove every open metric ball is open.', 'For $x\\in B(a,r)$ choose radius $r-d(a,x)>0$ and use the triangle inequality.'), ('Closed balls are closed', 'Prove every closed metric ball is closed.', 'If $x_n$ lies in the ball and converges to $x$, continuity of $y\\mapsto d(a,y)$ gives $d(a,x)\\le r$.'), ('Sphere is closed', 'Show $\\{x:\\|x\\|=1\\}$ is closed in a normed space.', 'The norm is continuous by the reverse triangle inequality, so the sphere is the inverse image of the closed singleton $\\{1\\}$.'), ('Boundary criterion', 'Show $x\\in\\partial A$ iff every ball about $x$ meets both $A$ and its complement.', 'Membership in the closure gives intersection with $A$; failure to be interior gives intersection with the complement.'), ('Closure of rationals', 'Prove $\\overline{\\mathbb Q}=\\mathbb R$.', 'Rational density says every real ball contains a rational point.'), ('Interior of rationals', 'Show $\\mathbb Q^\\circ=\\varnothing$.', 'Every interval around a rational contains irrational points.'), ('A clopen subspace piece', 'In $Y=(-\\infty,0)\\cup(0,\\infty)$, show $(0,\\infty)$ is clopen relative to $Y$.', 'It and its complement are intersections of $Y$ with ambient open half-lines.'), ('Closure of a finite union', 'Prove $\\overline{A\\cup B}=\\overline A\\cup\\overline B$.', 'The right side is closed and contains the union; monotonicity of closure gives the reverse inclusion.'), ('Interior of an intersection', 'Prove $(A\\cap B)^\\circ=A^\\circ\\cap B^\\circ$.', 'The right side is open and contained in the intersection; every open subset of the intersection lies in both interiors.'), ('Limit-point sequence', 'If $x$ is a limit point of $A$ in a metric space, construct a sequence of points of $A\\setminus\\{x\\}$ converging to $x$.', 'Choose $x_n\\in A\\cap(B(x,1/n)\\setminus\\{x\\})$; then $d(x_n,x)<1/n$.'), ('Topology synthesis', 'Why can topology be specified by open sets without mentioning a metric?', 'Convergence, closedness, continuity, compactness, connectedness, interior, closure, and boundary can all be defined from the family of open sets.')], 'exercises': [('Is $(0,1)$ open in $\\mathbb R$?', 'Choose a point-dependent radius.', 'Yes.'), ('Is $[0,1]$ closed?', 'Inspect the complement.', 'Yes.'), ('Find $\\partial(0,1)$.', 'Use closure minus interior.', 'It is $\\{0,1\\}$.'), ('Find $\\overline{\\mathbb Z}$ in $\\mathbb R$.', 'Is $\\mathbb Z$ closed?', 'It equals $\\mathbb Z$.'), ('Show $\\varnothing$ and $X$ are clopen.', 'Use complements.', 'Each is open and the complement of the other.'), ('Are arbitrary intersections of open sets open?', 'Use shrinking intervals.', 'No; $\\cap_n(-1/n,1/n)=\\{0\\}$.'), ('Find $[0,1]^\\circ$.', 'Endpoints fail the ball condition.', 'It is $(0,1)$.'), ('Show $A^\\circ\\subset A\\subset\\overline A$.', 'Use the defining extremal properties.', 'Both inclusions are immediate from the definitions.')]}, 'II/05': {'intro': 'Metric spaces isolate the role of distance in analysis. Continuity becomes preservation of local closeness, with equivalent epsilon-delta, sequential, and open-set formulations.', 'sections': [('Metrics', 'A metric is nonnegative, definite, symmetric, and satisfies the triangle inequality.'), ('Metric examples', 'Norm metrics, discrete metrics, and bounded transforms of metrics show how one set can carry different geometries.'), ('Metric convergence', 'A sequence converges exactly when its distance to the limit tends to zero.'), ('Continuity at a point', 'Output tolerances are controlled by sufficiently small input tolerances.'), ('Sequential continuity', 'In metric spaces continuity is equivalent to preserving sequential limits.'), ('Open-set continuity', 'Continuity is equivalent to inverse images of open sets being open.'), ('Uniform continuity', 'One input scale must work simultaneously at every point.'), ('Lipschitz maps', 'A Lipschitz estimate gives quantitative control and automatically implies uniform continuity.')], 'theorems': [('Sequential criterion', 'A map between metric spaces is continuous iff it preserves limits of sequences.', 'Continuity transfers epsilon estimates to a convergent sequence. Failure of continuity creates points within $1/n$ whose images stay a fixed distance away.'), ('Open-set criterion', 'A map is continuous iff the inverse image of every open set is open.', 'At a point in a preimage, continuity pulls back a small target ball; conversely apply openness to balls around the image point.'), ('Lipschitz implies uniform continuity', 'If $d(f(x),f(y))\\le Ld(x,y)$, then $f$ is uniformly continuous.', 'For $L>0$ choose $\\delta=\\varepsilon/L$; for $L=0$ the map is constant.')], 'dossiers': [('Discrete metric topology', 'Show every subset is open in the discrete metric.', 'For any point $x$, the ball $B(x,1/2)$ is the singleton $\\{x\\}$.'), ('Norm gives a metric', 'Prove $d(x,y)=\\|x-y\\|$ is a metric.', 'Definiteness and symmetry come from norm axioms, and the metric triangle inequality is the norm triangle inequality.'), ('Distance to a fixed point is Lipschitz', 'Show $x\\mapsto d(x,a)$ is $1$-Lipschitz.', 'The triangle inequality gives $|d(x,a)-d(y,a)|\\le d(x,y)$.'), ('A sequential discontinuity witness', 'Define $f(0)=0$ and $f(x)=1/x$ otherwise. Show discontinuity at zero.', 'Take $x_n=1/n\\to0$; then $f(x_n)=n$ does not converge to $0$.'), ('Square is not uniformly continuous on $\\mathbb R$', 'Produce nearby points with separated squares.', 'Take $x_n=n$, $y_n=n+1/n$; input distance tends to zero while square difference tends to $2$.'), ('Square on a bounded interval', 'Show $x^2$ is uniformly continuous on $[-M,M]$.', '$|x^2-y^2|\\le2M|x-y|$, so it is Lipschitz there.'), ('Composition', 'Prove the composition of continuous maps is continuous.', 'Inverse images compose: $(g\\circ f)^{-1}(U)=f^{-1}(g^{-1}(U))$.'), ('A bounded equivalent metric', 'Show $\\rho=d/(1+d)$ has the same convergent sequences as $d$.', '$\\rho\\le d$, while for small $\\rho$, $d=\\rho/(1-\\rho)\\le2\\rho$.'), ('Closed-set criterion', 'Show continuous maps pull closed sets back to closed sets.', 'Take complements and use the open-set criterion.'), ('Uniform continuity preserves Cauchy sequences', 'Prove the claim.', 'A uniform delta converts a Cauchy input tail into an epsilon-close image tail.'), ('Lipschitz diameter control', 'Show $\\operatorname{diam}f(A)\\le L\\operatorname{diam}A$.', 'Apply the Lipschitz inequality to every pair and take the supremum.'), ('Continuity synthesis', 'Why do inverse images appear in the topological definition?', 'Inverse images preserve arbitrary unions and finite intersections exactly, matching the axioms for open sets.')], 'exercises': [('Verify the triangle inequality for the discrete metric.', 'Consider whether endpoints agree.', 'If endpoints differ, at least one leg has length $1$.'), ('Is $f(x)=3x$ Lipschitz?', 'Compute differences.', 'Yes, with constant $3$.'), ('Show a constant map is uniformly continuous.', 'Output distance is zero.', 'Any positive delta works.'), ('Are sums of continuous real functions continuous?', 'Use limits or epsilon bounds.', 'Yes.'), ('Show $|x|$ is continuous.', 'Use reverse triangle inequality.', 'It is $1$-Lipschitz.'), ('Characterize convergence in the discrete metric.', 'Use epsilon $1/2$.', 'A convergent sequence is eventually constant.'), ('Does uniform continuity imply continuity?', 'Fix a point.', 'Yes.'), ('Give a continuous but not uniformly continuous map on $\\mathbb R$.', 'Use quadratic growth.', '$x^2$ is a standard example.')]}, 'II/06': {'intro': 'Compactness is the finiteness principle of analysis. It converts infinite covers into finite subcovers, arbitrary sequences into convergent subsequences, and local continuity into global boundedness and uniform control.', 'sections': [('Open-cover compactness', 'Every open cover of a compact space has a finite subcover.'), ('Sequential compactness', 'In metric spaces compactness is equivalent to every sequence having a convergent subsequence with limit in the space.'), ('Heine--Borel', 'In Euclidean space compact sets are exactly the closed and bounded sets.'), ('Bolzano--Weierstrass', 'Every bounded sequence in Euclidean space has a convergent subsequence.'), ('Continuous images', 'Continuous images of compact spaces are compact.'), ('Extreme values', 'Continuous real-valued functions on compact sets attain maxima and minima.'), ('Uniform continuity', 'Continuous maps on compact metric domains are uniformly continuous.'), ('Completeness and total boundedness', 'A metric space is compact exactly when it is complete and totally bounded.')], 'theorems': [('Continuous image theorem', 'If $K$ is compact and $f$ is continuous, then $f(K)$ is compact.', 'Pull an open cover of the image back to $K$, extract a finite subcover, and push the corresponding finite family forward.'), ('Extreme-value theorem', 'A continuous real function on nonempty compact $K$ attains its maximum and minimum.', 'Its image is compact in $\\mathbb R$, hence closed and bounded; its supremum and infimum belong to the image.'), ('Heine--Cantor', 'A continuous map on a compact metric domain is uniformly continuous.', 'Otherwise choose pairs arbitrarily close with images separated by a fixed epsilon; a convergent subsequence of one side forces both sides to the same limit, contradicting continuity.')], 'dossiers': [('Open interval is not compact', 'Use an open cover to show $(0,1)$ is not compact.', 'The sets $(1/n,1)$ for $n\\ge2$ cover $(0,1)$ but no finite subfamily covers points near zero.'), ('Sequential noncompactness', 'Show $(0,1]$ is not compact using a sequence.', 'The sequence $1/n$ has no subsequence converging to a point of $(0,1]$.'), ('Compact sets are closed', 'Prove this in metric spaces.', 'For $x\\notin K$, the continuous distance to $x$ attains a positive minimum on compact $K$, leaving a ball around $x$ disjoint from $K$.'), ('Compact sets are bounded', 'Prove it directly from an open cover.', 'The increasing balls $B(x_0,n)$ cover the space; finitely many reduce to one largest ball.'), ('Continuous real functions are bounded', 'Prove boundedness on compact domains.', 'The compact image in $\\mathbb R$ is bounded.'), ('Positive distance between disjoint compact sets', 'Prove disjoint compact $K,L$ have positive distance.', 'The continuous function $d(x,y)$ on compact $K\\times L$ attains a minimum; zero would force a common point.'), ('Finite intersection property', 'Prove compact spaces have it for closed sets.', 'If the total closed intersection were empty, their complements would give an open cover with a finite subcover, contradicting the finite intersection hypothesis.'), ('Nested compact sets', 'Show decreasing nonempty compact sets have nonempty intersection.', 'They satisfy the finite intersection property inside the first compact set.'), ('Heine--Cantor contradiction sequence', 'Describe the standard sequence proof.', 'Failure gives $d(x_n,y_n)<1/n$ but image distance at least $\\varepsilon_0$; compactness and continuity contradict this.'), ('Bolzano--Weierstrass by nested boxes', 'Sketch the construction.', 'Repeatedly choose a smaller closed box containing infinitely many sequence terms and diameters tending to zero; choose one term from each stage.'), ('Closed subset of compact is compact', 'Prove it by covers.', 'Add the open complement of the closed subset to any cover, extract a finite cover of the ambient compact set, then discard the complement.'), ('Compactness synthesis', 'Why is compactness a finite-extraction principle?', 'Its cover definition extracts finitely many neighborhoods, and its sequential form extracts one convergent subsequence from infinitely many terms.')], 'exercises': [('Is $\\{1/n:n\\ge1\\}\\cup\\{0\\}$ compact?', 'Check closed and bounded.', 'Yes.'), ('Is $\\mathbb Z$ compact in $\\mathbb R$?', 'Check boundedness.', 'No.'), ('Show every finite metric space is compact.', 'Choose one cover member per point.', 'Finitely many choices suffice.'), ('Does compactness imply completeness in metric spaces?', 'Use a convergent subsequence of a Cauchy sequence.', 'Yes.'), ('Is $(0,1)$ compact?', 'Use Heine--Borel.', 'No.'), ('Is a continuous image of compact closed in a metric codomain?', 'Compact subsets of metric spaces are closed.', 'Yes.'), ('Why is $[a,b]$ compact?', 'Use Heine--Borel.', 'It is closed and bounded.'), ('Must every sequence in a compact set converge?', 'Only a subsequence is guaranteed.', 'No; $(-1)^n$ in $\\{-1,1\\}$ is a counterexample.')]}, 'II/07': {'intro': 'Connectedness excludes decompositions into separated open pieces, while path connectedness asks for explicit continuous curves between points. These notions capture global cohesion that compactness and completeness do not.', 'sections': [('Connected spaces', 'A space is connected if it admits no separation into disjoint nonempty open pieces.'), ('Clopen criterion', 'Connected spaces have no nontrivial subset that is both open and closed.'), ('Connected subsets of the line', 'A subset of $\\mathbb R$ is connected exactly when it is an interval in the order-convex sense.'), ('Continuous images', 'Continuous maps preserve connectedness.'), ('Intermediate values', 'The intermediate-value theorem follows because continuous images of intervals are intervals.'), ('Path connectedness', 'A path is a continuous map from $[0,1]$ joining two prescribed endpoints.'), ('Path connected implies connected', 'A path cannot cross a separation without separating the interval parameter.'), ('Components', 'Connected and path components are maximal subsets with the corresponding cohesion property.')], 'theorems': [('Continuous image theorem', 'The continuous image of a connected space is connected.', 'A separation of the image pulls back to a separation of the domain.'), ('Intervals are connected', 'Every real interval is connected.', 'A hypothetical separation and a supremum argument at the interface produce a point that cannot consistently belong to either relatively open side.'), ('Path connected implies connected', 'Every path-connected space is connected.', 'A separation of the space would pull back along a path joining opposite sides to a separation of $[0,1]$.')], 'dossiers': [('Clopen criterion', 'Prove connectedness is equivalent to having only trivial clopen subsets.', 'A nontrivial clopen set and its complement form a separation, and every separation makes each side clopen.'), ('Punctured line', 'Show $\\mathbb R\\setminus\\{0\\}$ is disconnected.', 'The negative and positive half-lines are disjoint nonempty relatively open sets covering it.'), ('Connected subsets of the line', 'If $A\\subset\\mathbb R$ is connected and $x<z<y$ with $x,y\\in A$, show $z\\in A$.', 'If $z\\notin A$, split $A$ at $z$ into points below and above, creating a separation.'), ('Intermediate-value theorem', 'Derive it from connectedness.', 'The continuous image of $[a,b]$ is connected in $\\mathbb R$, hence an interval containing all values between endpoint values.'), ('Convex implies path connected', 'Prove every convex subset of a normed vector space is path connected.', 'The straight-line path $(1-t)x+ty$ remains in the convex set.'), ('Path components are disjoint', 'Show two path components are equal or disjoint.', 'If they meet, concatenate paths through a common point to show their union is path connected, contradicting maximality unless they coincide.'), ('Union through a common point', 'Show a union of connected sets with a common point is connected.', 'Any separation would place the common point on one side; each connected member meeting that side must lie entirely there.'), ('Closure preserves connectedness', 'Prove the closure of a connected set is connected.', 'A separation of the closure would meet the original dense connected set on both sides and induce a separation of it.'), ('Continuous image of a path', 'Show continuous maps preserve path connectedness.', 'Compose the original path with the continuous map.'), ('Components are closed', 'Prove every connected component is closed.', 'The closure of a connected set is connected and contains the component; maximality forces equality.'), ('Products of path-connected spaces', 'Show $X\\times Y$ is path connected when both factors are.', 'Pair paths coordinatewise: $t\\mapsto(\\alpha(t),\\beta(t))$.'), ('Connectedness synthesis', 'Contrast connectedness with compactness.', 'Connectedness excludes a global split into separated regions; compactness excludes infinite escape by finite extraction. Neither implies the other in general.')], 'exercises': [('Is $[0,1]\\cup[2,3]$ connected?', 'Find a separation.', 'No.'), ('Is $\\mathbb R$ path connected?', 'Use straight lines.', 'Yes.'), ('Are continuous images of connected sets connected?', 'Use the theorem.', 'Yes.'), ('Are connected subsets of $\\mathbb R$ intervals?', 'Use an intermediate-point argument.', 'Yes.'), ('Show a singleton is connected.', 'There is no nontrivial split.', 'Its only clopen subsets are trivial.'), ('Is $\\mathbb Q$ connected?', 'Cut at an irrational number.', 'No.'), ('Does path connected imply connected?', 'Use interval connectedness.', 'Yes.'), ('Does connected imply path connected?', 'Recall a classical plane counterexample.', "No; the topologist's sine curve is a standard counterexample.")]}}
